"""Emit the character tables CPython's `int(s, base)` uses, as Go source.

`uuid.UUID(hex=...)` ends in `int(hex, 16)`, so a Go stand-in for it needs
`int`'s accept set, not "32 hex digits". Before parsing, CPython transforms the
string (`_PyUnicode_TransformDecimalAndSpaceToASCII`):

  * every character in the Nd general category becomes its ASCII digit;
  * every character `int` treats as a space becomes U+0020;
  * everything else is left alone.

Only then is the ASCII grammar applied. That single fact explains every
measured oddity, which is why the Go side reproduces the transform rather than
the outcomes:

    int('٠x1', 16) == 1     # U+0660 becomes '0', so '0x' IS a prefix here
    int('1\xa01', 16)       # raises: U+00A0 becomes ' ', giving '1 1'
    int('1​', 16)      # raises: U+200B is NOT in the space set

# Why the tables are generated rather than taken from Go's `unicode` package

They disagree, in the direction that hurts. Measured today:

    CPython 3.14.7  unicodedata 16.0.0   760 Nd codepoints
    Go 1.27         unicode.Version 17.0.0   770 Nd codepoints
    Go-only: U+11DE0..U+11DE9 (ten codepoints)   CPython-only: none

Using `unicode.Is(unicode.Nd, r)` would therefore ACCEPT ten codepoints the
reference REJECTS. For the scope-gate caller — which runs before the bridge
validates and writes rows — accepting what the reference rejects is the defect
class this whole package exists to prevent. Freezing the reference's own table
removes the Unicode-version axis instead of tracking it.

The generated file records the interpreter and Unicode version it was measured
from. Regenerate when the shipped interpreter moves:

    python tests/fixtures/generate_python_int_grammar_table.py \
        --out internal/pythonparity/pythonint_table.go
"""

from __future__ import annotations

import argparse
import platform
import sys
import unicodedata

HEADER = """// Code generated by tests/fixtures/generate_python_int_grammar_table.py. DO NOT EDIT.
//
// Measured from CPython {python} (unicodedata {unidata}).
//
// These are the tables CPython's int() uses to transform a string before
// parsing it. They are frozen here rather than read from Go's unicode package
// because the two track different Unicode versions, and Go's is WIDER: it has
// {go_only} Nd codepoints CPython lacks, so deriving the set from Go would
// accept values the reference rejects.

package pythonparity

// pythonNdRuns holds every Nd (decimal digit) run CPython knows, as inclusive
// [lo, hi] rune pairs. Every run is exactly ten codepoints and starts at the
// digit zero, so a rune's value is `r - lo`. That is a property of the Unicode
// data, asserted by the generator rather than assumed here.
var pythonNdRuns = [...][2]rune{{
{runs}}}

// pythonIntSpaces holds every character CPython's int() folds to a space.
//
// It is NOT `unicode.IsSpace`, and it is NOT `str.isspace()`: U+001C..U+001F
// are whitespace to both of those and are REJECTED by int(). Measured, not
// described.
var pythonIntSpaces = [...]rune{{
{spaces}}}
"""


def measure_nd_runs() -> list[tuple[int, int]]:
    """Collapse the Nd category into runs whose value is the offset from `lo`."""
    runs: list[list[int]] = []
    for codepoint in range(0x110000):
        char = chr(codepoint)
        if unicodedata.category(char) != "Nd":
            continue
        value = unicodedata.digit(char)
        if runs and codepoint == runs[-1][1] + 1 and value == runs[-1][2] + 1:
            runs[-1][1] = codepoint
            runs[-1][2] = value
        else:
            runs.append([codepoint, codepoint, value])

    for lo, hi, _ in runs:
        # The Go side computes a digit's value as `r - lo`. That is only correct
        # if every run is a full 0..9 ladder. Assert it here so a future Unicode
        # release that breaks the property fails the GENERATOR loudly instead of
        # silently mis-valuing digits at runtime.
        assert unicodedata.digit(chr(lo)) == 0, f"run at {lo:#x} does not start at 0"
        assert hi - lo == 9, f"run {lo:#x}..{hi:#x} is not ten codepoints"
    return [(lo, hi) for lo, hi, _ in runs]


def measure_space_set() -> list[int]:
    """Every character int(..., 16) accepts as surrounding whitespace.

    Probed rather than derived: the value is placed both before and after a
    digit, so a character only lands in the set if it is a space on both sides.
    """
    spaces: list[int] = []
    for codepoint in range(0x110000):
        char = chr(codepoint)
        try:
            int(char + "1" + char, 16)
        except ValueError:
            continue
        if unicodedata.category(char) == "Nd" or char in "0123456789abcdefABCDEF":
            continue  # a digit, not a space
        spaces.append(codepoint)
    return spaces


def render(runs: list[tuple[int, int]], spaces: list[int], go_only: int) -> str:
    run_lines = "".join(f"\t{{{lo:#x}, {hi:#x}}},\n" for lo, hi in runs)
    space_lines = ""
    for index in range(0, len(spaces), 8):
        chunk = spaces[index : index + 8]
        space_lines += "\t" + " ".join(f"{cp:#x}," for cp in chunk) + "\n"
    return HEADER.format(
        python=platform.python_version(),
        unidata=unicodedata.unidata_version,
        go_only=go_only,
        runs=run_lines,
        spaces=space_lines,
    )


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--out", default="internal/pythonparity/pythonint_table.go")
    parser.add_argument("--stdout", action="store_true")
    parser.add_argument(
        "--go-only-count",
        type=int,
        default=10,
        help="Nd codepoints Go has and CPython does not, for the header note.",
    )
    args = parser.parse_args()

    payload = render(measure_nd_runs(), measure_space_set(), args.go_only_count)
    if args.stdout:
        sys.stdout.write(payload)
    else:
        with open(args.out, "w", encoding="utf-8") as handle:
            handle.write(payload)
        print(f"written {args.out}", file=sys.stderr)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
